WITH sep_orders AS (
  SELECT order_id FROM silver.orders WHERE order_date >= DATE '2026-09-01' AND order_date < DATE '2026-10-01'
),
returned_orders AS (
  SELECT DISTINCT order_id FROM silver.returns WHERE order_id IN (SELECT order_id FROM sep_orders)
)
SELECT 
  (SELECT COUNT(*) FROM sep_orders) AS total_orders,
  (SELECT COUNT(*) FROM returned_orders) AS returned_orders,
  ROUND(100.0 * (SELECT COUNT(*) FROM returned_orders) / NULLIF((SELECT COUNT(*) FROM sep_orders),0), 2) AS return_share_percent;

